IDF_HEADER = ['.HEADER', 'BOARD_FILE 3.0 "Fusion" 2026/01/01.00:00:00 1', '"%s" MM' % NAME, '.END_HEADER', '.PLACEMENT']

CM = 0.1  # the Fusion API works in centimetres
NEW = adsk.fusion.FeatureOperations.NewBodyFeatureOperation


def point(x, y):
    return adsk.core.Point3D.create(x * CM, y * CM, 0)


def build(root):
    sketch = root.sketches.add(root.xYConstructionPlane)
    lines = sketch.sketchCurves.sketchLines
    for loop in [OUTLINE] + CUTOUTS:
        for i in range(len(loop)):
            lines.addByTwoPoints(point(*loop[i]), point(*loop[(i + 1) % len(loop)]))
    for x, y, d in HOLES:
        sketch.sketchCurves.sketchCircles.addByCenterRadius(point(x, y), d / 2 * CM)
    profile = max(sketch.profiles, key=lambda p: p.areaProperties().area)
    extrudes = root.features.extrudeFeatures
    extrudes.addSimple(profile, adsk.core.ValueInput.createByReal(THICKNESS * CM), NEW).bodies.item(0).name = "Board"
    for ref, x, y, rot, bottom, x0, y0, x1, y1, z0, h in PARTS:
        place = adsk.core.Matrix3D.create()
        place.translation = adsk.core.Vector3D.create(x * CM, y * CM, 0)
        comp = root.occurrences.addNewComponent(place).component
        comp.name = ref
        box = comp.sketches.add(comp.xYConstructionPlane)
        box.sketchCurves.sketchLines.addTwoPointRectangle(point(x0 - x, y0 - y), point(x1 - x, y1 - y))
        body = comp.features.extrudeFeatures.createInput(box.profiles.item(0), NEW)
        body.setDistanceExtent(False, adsk.core.ValueInput.createByReal(h * CM))
        start = -z0 - h if bottom else THICKNESS + z0
        body.startExtent = adsk.fusion.OffsetStartDefinition.create(adsk.core.ValueInput.createByReal(start * CM))
        comp.features.extrudeFeatures.add(body)
        comp.attributes.add("SiEDA", "ref", ref)
        comp.attributes.add("SiEDA", "rotation", str(rot))
        comp.attributes.add("SiEDA", "bottom", "1" if bottom else "0")


def send_back(ui, parts):
    dialog = ui.createFileDialog()
    dialog.title = "Placement for SiEDA (IDF)"
    dialog.filter = "IDF board (*.emn)"
    dialog.initialFilename = NAME + "-placement.emn"
    if dialog.showSave() != adsk.core.DialogResults.DialogOK:
        return
    lines = list(IDF_HEADER)
    for occurrence in parts:
        a = occurrence.component.attributes
        origin, x_axis, _, _ = occurrence.transform2.getAsCoordinateSystem()
        angle = (float(a.itemByName("SiEDA", "rotation").value) + math.degrees(math.atan2(x_axis.y, x_axis.x))) % 360
        side = "BOTTOM" if a.itemByName("SiEDA", "bottom").value == "1" else "TOP"
        lines.append('"PART" "PART" "%s"' % a.itemByName("SiEDA", "ref").value)
        lines.append("%.4f %.4f 0 %.2f %s PLACED" % (origin.x / CM, origin.y / CM, angle, side))
    lines.append(".END_PLACEMENT")
    with open(dialog.filename, "w") as f:
        f.write("\n".join(lines) + "\n")
    ui.messageBox("Placement written. In SiEDA: File > Import MCAD Placement (IDF).")


def run(context):
    app = adsk.core.Application.get()
    root = adsk.fusion.Design.cast(app.activeProduct).rootComponent
    parts = [o for o in root.occurrences if o.component.attributes.itemByName("SiEDA", "ref")]
    if parts:
        send_back(app.userInterface, parts)
    else:
        build(root)
